CREATE TABLE `error_rule`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `auth` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '验证字段',
  `field` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '验证字段名称',
  `rule` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '验证规则',
  `relation` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '',
  `relation_rule` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '',
  `level` tinyint(4) NOT NULL COMMENT '错误等级',
  `desc` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `down` double(2, 1) NOT NULL COMMENT '扣分',
  `type` tinyint(4) NOT NULL DEFAULT 0 COMMENT '缺陷分类0患者基本信息1诊疗信息2费用信息',
  `error_type` tinyint(4) NOT NULL DEFAULT 0 COMMENT '缺陷类型0逻辑性1规范性2编码',
  `category` tinyint(4) NOT NULL DEFAULT 0 COMMENT '缺陷类别0:A类,1:B类,2:C类,3D类',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0启用 1:停用',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `error_rule_auth_index`(`auth`) USING BTREE,
  INDEX `error_rule_field_index`(`field`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1434 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Compact;

